import{_ as a,H as _,f as t,i}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"Q85 | 评估标准：AI产品验收标准怎么定？","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q85｜评估标准：AI产品验收标准怎么定？.md","filePath":"致程序员：AI百问百答/Q85｜评估标准：AI产品验收标准怎么定？.md","lastUpdated":1795559851000}'),l={name:"致程序员：AI百问百答/Q85｜评估标准：AI产品验收标准怎么定？.md"};function p(r,e,o,s,n,c){return _(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="q85-评估标准-ai产品验收标准怎么定" tabindex="-1">Q85 | 评估标准：AI产品验收标准怎么定？ <a class="header-anchor" href="#q85-评估标准-ai产品验收标准怎么定" aria-label="Permalink to &quot;Q85 | 评估标准：AI产品验收标准怎么定？&quot;">​</a></h1><ul><li>作者介绍：黄佳，新加坡科研局资深研发工程师</li></ul><p>Q：针对 AI 的产品，如何评价 AI 的产出的准确性、是否满足需要等，有哪些构建回收标准的方法或者思路？</p><p>黄佳：从大模型检索知识库或查找网页，然后生成回答的角度，分析评估指标如下。</p><p>一、标准指标评估</p><ul><li><p>文本生成：BLEU、ROUGE、METEOR、BERTScore；</p></li><li><p>分类 / 决策：Accuracy、Precision、Recall、F1 Score；</p></li><li><p>检索生成（RAG）：Hit@k、MRR、nDCG、Faithfulness、 Groundedness。</p></li><li><p>人工标注 + 多维打分：人工打分维度包括相关性、正确性、语言流畅性、信息新颖性等。</p></li></ul><p>二、回收标准设计方法</p><p>建立反馈机制，如“用户点赞 / 纠错”“点击率”回传给模型系统；也可有一个动态标签池定期引入高质量人工标注数据，用于校验和微调。</p>',8)])])}const u=a(l,[["render",p]]);export{A as __pageData,u as default};
